Lemma map_upd_nth : forall {A B} (f : A -> B) l i x, List.map f (upd_nth l i x) = upd_nth (List.map f l) i (f x).
Proof. induction l as [|y l IH]; intros [|i] x; cbn; [reflexivity| reflexivity| reflexivity| rewrite IH; reflexivity]. Qed.
